package com.yeyamo_mobile.api.discovery_service.infrastructure.postgis;import java.time.Instant;import java.util.UUID;import jakarta.persistence.*;import com.yeyamo_mobile.api.discovery_service.domain.model.DiscoveryType;
@Entity@Table(name="discovery_documents")public class DiscoveryDocumentEntity{@Id private UUID id;@Column(name="source_id",nullable=false,unique=true,length=120)private String sourceId;@Enumerated(EnumType.STRING)@Column(nullable=false,length=30)private DiscoveryType type;@Column(nullable=false,length=300)private String title;@Column(columnDefinition="TEXT")private String description;@Column(name="category_code",length=100)private String categoryCode;@Column(name="region_code",length=40)private String regionCode;@Column(length=160)private String city;private Double latitude;private Double longitude;@Column(name="author_id",length=120)private String authorId;@Column(name="trend_score",nullable=false)private double trendScore;@Column(nullable=false)private boolean active;@Column(name="published_at")private Instant publishedAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;@Version private long version;public UUID getId(){return id;}public void setId(UUID v){id=v;}public String getSourceId(){return sourceId;}public void setSourceId(String v){sourceId=v;}public DiscoveryType getType(){return type;}public void setType(DiscoveryType v){type=v;}public String getTitle(){return title;}public void setTitle(String v){title=v;}public String getDescription(){return description;}public void setDescription(String v){description=v;}public String getCategoryCode(){return categoryCode;}public void setCategoryCode(String v){categoryCode=v;}public String getRegionCode(){return regionCode;}public void setRegionCode(String v){regionCode=v;}public String getCity(){return city;}public void setCity(String v){city=v;}public Double getLatitude(){return latitude;}public void setLatitude(Double v){latitude=v;}public Double getLongitude(){return longitude;}public void setLongitude(Double v){longitude=v;}public String getAuthorId(){return authorId;}public void setAuthorId(String v){authorId=v;}public double getTrendScore(){return trendScore;}public void setTrendScore(double v){trendScore=v;}public boolean isActive(){return active;}public void setActive(boolean v){active=v;}public Instant getPublishedAt(){return publishedAt;}public void setPublishedAt(Instant v){publishedAt=v;}public Instant getUpdatedAt(){return updatedAt;}public void setUpdatedAt(Instant v){updatedAt=v;}}
